INSERT INTO Books VALUES(1,'iO5pApw2J7EC','The Great Gatsby','["F. Scott Fitzgerald"]','The Great Gatsby, F. Scott Fitzgerald''s third book, stands as the supreme achievement of his career. First published in 1925, this quintessential novel of the Jazz Age has been acclaimed by generations of readers.','http://books.google.com/books/content?id=iO5pApw2J7EC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api','en',180,'1925-04-10','current','2026-01-20 20:05:50.523 +00:00','2026-01-20 20:05:50.523 +00:00','2026-01-20 20:05:50.523 +00:00',NULL);
INSERT INTO Books VALUES(2,'A-hPCwAAQBAJ','Project Hail Mary','["Andy Weir"]','Ryland Grace is the sole survivor on a desperate, last-chance mission—and if he fails, humanity and the earth itself will perish.','http://books.google.com/books/content?id=A-hPCwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api','en',476,'2021-05-04','candidate',NULL,'2026-01-20 20:05:50.523 +00:00','2026-01-20 20:05:50.523 +00:00',NULL);
INSERT INTO Books VALUES(3,'B1hSG45JCX4C','Dune','["Frank Herbert"]','Set on the desert planet Arrakis, Dune is the story of the boy Paul Atreides, heir to a noble family tasked with ruling an inhospitable world where the only thing of value is the "spice" melange.','http://books.google.com/books/content?id=B1hSG45JCX4C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api','en',412,'1965-06-01','candidate',NULL,'2026-01-20 20:05:50.523 +00:00','2026-01-20 20:05:50.523 +00:00',NULL);
INSERT INTO Books VALUES(4,'PGR2AwAAQBAJ','To Kill a Mockingbird','["Harper Lee"]','Voted America''s Best-Loved Novel in PBS''s The Great American Read. Harper Lee''s Pulitzer Prize-winning masterwork of honor and injustice in the deep South.','http://books.google.com/books/content?id=PGR2AwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api','en',281,'1960-07-11','read',NULL,'2026-01-20 20:05:50.523 +00:00','2026-01-20 20:05:50.523 +00:00',NULL);
INSERT INTO Comments VALUES(1,'Alice','The symbolism of the green light is just masterpiece work.','2026-01-20 20:05:50.526 +00:00','2026-01-20 20:05:50.526 +00:00',NULL);
INSERT INTO Comments VALUES(2,'Bob','I actually found the characters quite unlikeable, but I think that was the point?','2026-01-20 20:05:50.526 +00:00','2026-01-20 20:05:50.526 +00:00',NULL);
INSERT INTO Comments VALUES(3,'Charlie','Classic for a reason. Quick read but stays with you.','2026-01-20 20:05:50.526 +00:00','2026-01-20 20:05:50.526 +00:00',NULL);
