PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE `Books` (`id` INTEGER PRIMARY KEY, `googleId` VARCHAR(255) UNIQUE, `title` VARCHAR(255), `authors` VARCHAR(255), `description` TEXT, `coverUrl` VARCHAR(255), `language` VARCHAR(255), `pageCount` INTEGER, `publishedDate` VARCHAR(255), `status` TEXT DEFAULT 'candidate', `selectedDate` DATETIME, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, `suggesterId` VARCHAR(255));
CREATE TABLE `Comments` (`id` INTEGER PRIMARY KEY, `username` VARCHAR(255), `text` TEXT, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, `BookId` INTEGER REFERENCES `Books` (`id`) ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE `Subscribers` (`id` INTEGER PRIMARY KEY, `email` VARCHAR(255), `phoneNumber` VARCHAR(255), `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL);
CREATE TABLE `Meetings` (`id` INTEGER PRIMARY KEY, `date` DATETIME NOT NULL, `topic` VARCHAR(255) NOT NULL, `location` VARCHAR(255) DEFAULT 'Online', `host` VARCHAR(255) DEFAULT 'Group Curator', `description` TEXT, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL);
CREATE TABLE `Participants` (`id` INTEGER PRIMARY KEY, `name` VARCHAR(255) NOT NULL, `email` VARCHAR(255), `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, `MeetingId` INTEGER REFERENCES `Meetings` (`id`) ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE `MeetingBooks` (`createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, `MeetingId` INTEGER NOT NULL UNIQUE REFERENCES `Meetings` (`id`), `BookId` INTEGER NOT NULL UNIQUE REFERENCES `Books` (`id`), PRIMARY KEY (`MeetingId`, `BookId`));
COMMIT;
